// Consulta a planilha de pedidos do ERP: procura por número (pedido, OC, NF, OP, solicitação,
// material, cliente) ou por texto (cliente, material, fornecedor...) e devolve só os campos úteis.
// tipo: pedido (padrão), atrasados, compra, solicitacao, producao ou resumo.
const entrada = $('Quando a Kira consultar os pedidos').first().json;
const arquivo = $('Informações do arquivo').first()?.json ?? {};
const linhas = $input.all().map((i) => i.json);

const normalizar = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ./-]/g, '').replace(/\s+/g, ' ').trim();
const vazio = (v) => v === undefined || v === null || String(v).trim() === '';
const texto = (v) => (vazio(v) ? '' : String(v).trim());
function data(v) {
  if (vazio(v)) return '';
  const n = Number(v);
  if (Number.isFinite(n) && n > 20000 && n < 80000) {
    return DateTime.fromMillis(Math.round((n - 25569) * 86400000), { zone: 'UTC' }).toFormat('dd/MM/yyyy');
  }
  return texto(v);
}
const numero = (v) => {
  const n = Number(String(v ?? '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const atrasado = (l) => {
  const n = numero(l.ATRASO);
  if (n !== null) return n > 0;
  return /^(s|sim|atrasad)/i.test(texto(l.ATRASO));
};

const CODIGOS = ['CD_PEDIDO', 'CD_ORDEM_COMPRA', 'NF', 'ULTIMA_NF_FATURADA', 'OP', 'CD_ORDEM', 'CD_SOLICITACAO', 'CD_MATERIAL', 'CD_CLIENTE', 'PARTNUMBER', 'NF_ENTRADA', 'PROJETO'];
const TEXTOS = ['CLIENTE_FANTASIA', 'CLIENTE_NOME_COMPLETO', 'DESC_MATERIAL', 'PARTNUMBER', 'NOME_FORNECEDOR_OC', 'FORNECEDOR_NF_ENTRADA', 'DESC_UNIDADE_NEGOCIO', 'MUNICIPIO', 'UF', 'VENDEDOR_INTERNO_NOME', 'VENDEDOR_EXTERNO_NOME', 'OBSERVACAO', 'PROJETO', 'DESC_GRUPO', 'NOME_FABRICANTE', 'AREA'];

const termos = normalizar(entrada.busca).split(' ').filter(Boolean);
const tipo = normalizar(entrada.tipo) || 'pedido';
const limite = Math.min(Math.max(Number(entrada.limite) || 10, 1), 25);

const combina = (l) =>
  termos.every((t) =>
    /^\d+$/.test(t)
      ? CODIGOS.some((c) => normalizar(l[c]).replace(/\.0+$/, '') === t)
      : TEXTOS.some((c) => normalizar(l[c]).includes(t)),
  );
const FILTROS = {
  atrasados: atrasado,
  compra: (l) => !vazio(l.CD_ORDEM),
  solicitacao: (l) => !vazio(l.CD_SOLICITACAO),
  producao: (l) => !vazio(l.OP) || !vazio(l.DEM_OP_CD_MAT),
};
const achadas = linhas.filter((l) => (!termos.length || combina(l)) && (!FILTROS[tipo] || FILTROS[tipo](l)));

const contar = (lista, campo) =>
  Object.entries(lista.reduce((acc, l) => ((acc[texto(l[campo]) || '(vazio)'] = (acc[texto(l[campo]) || '(vazio)'] ?? 0) + 1), acc), {}))
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([valor, itens]) => ({ valor, itens }));
const semVazios = (obj) =>
  Object.fromEntries(
    Object.entries(obj)
      .map(([k, v]) => [k, v && typeof v === 'object' && !Array.isArray(v) ? semVazios(v) : v])
      .filter(([, v]) => !(vazio(v) || (typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length))),
  );
const item = (l) =>
  semVazios({
    pedido: texto(l.CD_PEDIDO),
    item: texto(l.SEQUENCIA),
    emissao: data(l.DATA_EMISSAO),
    unidade: texto(l.DESC_UNIDADE_NEGOCIO),
    tipo_venda: texto(l.TIPO_VENDA),
    cliente: texto(l.CLIENTE_FANTASIA) || texto(l.CLIENTE_NOME_COMPLETO),
    cidade: [texto(l.MUNICIPIO), texto(l.UF)].filter(Boolean).join('/'),
    vendedor: texto(l.VENDEDOR_INTERNO_NOME) || texto(l.VENDEDOR_EXTERNO_NOME),
    material: [texto(l.CD_MATERIAL), texto(l.DESC_MATERIAL)].filter(Boolean).join(' - '),
    partnumber: texto(l.PARTNUMBER),
    quantidade: texto(l.QUANTIDADE),
    preco_unitario: texto(l.PR_UNITARIO),
    valor_total: texto(l.VL_TOTAL_ITEM),
    prazo_entrega: data(l.PRAZO_ENTREGA_ITEM),
    prazo_programado: data(l.PRAZO_PROGRAMADO_ITEM),
    situacao: texto(l.SITUACAO_PEDIDO),
    controle: texto(l.DESC_CONTROLE_PEDIDO),
    controle_item: texto(l.ITEM_DESC_CONTROLE),
    atraso: texto(l.ATRASO),
    area: texto(l.AREA),
    estoque_disponivel: texto(l.ESTOQUE_DISPONIVEL_ALM),
    estoque_em_transito: texto(l.ESTOQUE_FISICO_EM_TRANSITO),
    ordem_de_compra_cliente: texto(l.CD_ORDEM_COMPRA),
    nf: texto(l.NF) || texto(l.ULTIMA_NF_FATURADA),
    op: texto(l.OP),
    compra: {
      ordem: texto(l.CD_ORDEM),
      fornecedor: texto(l.NOME_FORNECEDOR_OC),
      quantidade: texto(l.QUANTIDADE_OC),
      situacao: texto(l.SITUACAO_ITEM_ORDEM),
      controle: texto(l.DESC_CONTROLE_ITEM_ORDEM),
      previsao_entrega: data(l.PREVISAO_ENTREGA_ITEM_ORDEM),
    },
    solicitacao: {
      numero: texto(l.CD_SOLICITACAO),
      data: data(l.DATA_SOLICITACAO),
      quantidade: texto(l.QUANTIDADE_ITEM_SOLICITACAO),
      controle: texto(l.DESC_CONTROLE_ITEM_SOLICITACAO),
    },
    wms: { status: texto(l.STATUS_WMS), situacao: texto(l.SITUACAO_WMS) },
    producao: {
      material: [texto(l.DEM_OP_CD_MAT), texto(l.DEM_OP_DESCRICAO)].filter(Boolean).join(' - '),
      necessaria: texto(l.DEM_OP_QT_NECESSARIA),
      atendida: texto(l.DEM_OP_QT_ATENDIDA),
      status_wms: texto(l.DEM_OP_STATUS_WMS),
    },
    observacao: texto(l.OBSERVACAO).slice(0, 200),
  });

const atualizadoEm = arquivo.lastModifiedDateTime
  ? DateTime.fromISO(arquivo.lastModifiedDateTime).setZone('America/Sao_Paulo').toFormat("dd/MM/yyyy 'às' HH:mm")
  : '';
const fonte = `Planilha ${arquivo.name || 'de pedidos'} do ERP${atualizadoEm ? `, atualizada em ${atualizadoEm}` : ''}`;
const resumo = {
  itens: achadas.length,
  pedidos: new Set(achadas.map((l) => texto(l.CD_PEDIDO))).size,
  itens_atrasados: achadas.filter(atrasado).length,
  por_situacao: contar(achadas, 'SITUACAO_PEDIDO'),
  por_controle: contar(achadas, 'DESC_CONTROLE_PEDIDO'),
};

return [
  {
    json: {
      fonte,
      busca: texto(entrada.busca),
      tipo,
      resumo,
      itens: tipo === 'resumo' ? [] : achadas.slice(0, limite).map(item),
      mais_itens: Math.max(achadas.length - limite, 0),
      orientacao: achadas.length
        ? 'Responda só com estes dados e cite a fonte e a data de atualização. Não invente nada que não esteja aqui.'
        : 'Nada encontrado. Diga isso ao dono, cite a fonte e a data de atualização e sugira buscar por outro número ou nome.',
    },
  },
];

// Resume o erro para a Kira explicar ao dono.
const item = $input.first().json;
const bruto = item.error ?? item;
const textos = [];
const coletar = (valor, profundidade = 0) => {
  if (!valor || profundidade > 4) return;
  if (typeof valor === 'string') {
    textos.push(valor);
    return;
  }
  if (typeof valor === 'object') {
    for (const chave of ['message', 'description']) {
      if (typeof valor[chave] === 'string') textos.push(valor[chave]);
    }
    coletar(valor.error, profundidade + 1);
  }
};
coletar(bruto);
const erro = [...new Set(textos.map((t) => t.trim()).filter(Boolean))].join(' — ').slice(0, 600) || 'erro desconhecido';

return [{ json: { ok: false, erro, orientacao: 'Não consegui ler a planilha de pedidos. Explique o erro ao dono em poucas palavras e não invente dados.' } }];
